package io.knowledgebrain.integration;
import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.integration.githubwork.v1.*;
final class GitHubWorkStore {
 record Item(UUID itemId,UUID repositoryId,UUID spaceId,String visibility,String sourceVisibility,String kind,long number,String externalId,String repositoryExternalId,String repositoryFullName,String title,String state,String authorLogin,Boolean draft,String createdAt,String updatedAt,String closedAt,String url,long version,String firstObservedAt,String observedAt,UUID observedBy){}
 record State(UUID repositoryId,UUID spaceId,String kind,long version,String lastSyncedAt,String repositoryState){}
 record Receipt(UUID syncId,UUID repositoryId,String kind,long syncVersion,String observedAt,int scannedCount,int observedCount,int importedCount,int updatedCount,int unchangedCount,boolean possiblyMore){}
 record Synced(State state,Receipt sync,boolean replay){} record Page<T>(List<T> items,UUID nextAfter){}record SyncPage(List<Receipt> items,Long nextBefore){}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Item snapshot){}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final GitHubStore repositories;private final UuidV7 ids;private final Clock clock;private final JsonMapper json=JsonMapper.builder().build();
 GitHubWorkStore(DataSource ds,Clock clock,GitHubStore repositories){sql=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;this.repositories=repositories;ids=new UuidV7(clock);}
 static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"GitHub work observation changed or identity mismatched");}
 State state(UUID space,UUID repo,String kind){GitHubWorkClient.kind(kind);var parent=repositories.get(space,repo);var rows=sql.query("SELECT version,observed_at FROM github_work_sync_state WHERE repository_id=? AND kind=?",(rs,n)->new State(repo,space,kind,rs.getLong(1),rs.getTimestamp(2).toInstant().toString(),parent.state()),repo,kind);return rows.isEmpty()?new State(repo,space,kind,0,null,parent.state()):rows.getFirst();}
 Synced replay(UUID space,UUID repo,String kind,UUID actor,String key,long expected){GitHubWorkClient.kind(kind);GitHubRules.key(key);var current=state(space,repo,kind);var rows=sql.query("SELECT expected_version,snapshot::text FROM github_work_receipt WHERE space_id=? AND repository_id=? AND kind=? AND actor_id=? AND request_key=?",(rs,n)->{if(rs.getLong(1)!=expected)throw conflict();return json.readValue(rs.getString(2),Receipt.class);},space,repo,kind,actor,key);return rows.isEmpty()?null:new Synced(current,rows.getFirst(),true);}
 Synced sync(UUID space,UUID repo,String kind,UUID actor,String key,long expected,GitHubWorkClient.Batch batch,String trace){GitHubWorkClient.kind(kind);GitHubRules.key(key);GitHubRules.id(actor.toString());if(expected<0||expected>=9007199254740991L||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw GitHubRules.bad();return tx.execute(t->{repositories.get(space,repo);sql.queryForObject("SELECT repository_id FROM github_repository WHERE repository_id=? AND space_id=? FOR UPDATE",UUID.class,repo,space);var retry=replay(space,repo,kind,actor,key,expected);if(retry!=null)return retry;var parent=repositories.get(space,repo);var state=state(space,repo,kind);if(state.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Work sync changed; reload current state");if(!parent.state().equals("ACTIVE"))throw conflict();if(batch==null||!batch.kind().equals(kind)||!parent.externalId().equals(batch.repository().externalId())||!GitHubRules.url(parent.url()).equals(GitHubRules.url(batch.repository().url()))||!parent.fullName().equals(batch.repository().fullName())||batch.scannedCount()<0||batch.scannedCount()>20||batch.items().size()>batch.scannedCount()||batch.possiblyMore()!=(batch.scannedCount()==20)||kind.equals("PULL_REQUEST")&&batch.items().size()!=batch.scannedCount())throw conflict();var numbers=new HashSet<Long>();var externals=new HashSet<String>();Instant now=clock.instant();int imported=0,updated=0,unchanged=0;for(var source:batch.items()){validate(parent,kind,source);if(!numbers.add(source.number())||!externals.add(source.externalId()))throw conflict();if(sql.queryForObject("SELECT count(*) FROM github_work_item WHERE repository_id=? AND external_id=? AND number<>?",Integer.class,repo,source.externalId(),source.number())>0)throw conflict();var rows=sql.query("SELECT snapshot::text FROM github_work_item WHERE repository_id=? AND number=?",(rs,n)->json.readValue(rs.getString(1),Item.class),repo,source.number());Item old=rows.isEmpty()?null:rows.getFirst();if(old!=null){if(!old.externalId().equals(source.externalId())||!old.kind().equals(kind)||!old.createdAt().equals(source.createdAt())||Instant.parse(source.updatedAt()).isBefore(Instant.parse(old.updatedAt())))throw conflict();if(equal(old,source)){unchanged++;continue;}}UUID item=old==null?ids.next():old.itemId();var value=new Item(item,repo,space,"PRIVATE","PUBLIC",kind,source.number(),source.externalId(),parent.externalId(),parent.fullName(),source.title(),source.state(),source.authorLogin(),source.draft(),source.createdAt(),source.updatedAt(),source.closedAt(),source.url(),old==null?1:Math.addExact(old.version(),1),old==null?now.toString():old.firstObservedAt(),now.toString(),actor);if(old==null){sql.update("INSERT INTO github_work_item VALUES (?,?,?,?,?,?,?,?,?::jsonb)",item,space,repo,kind,value.number(),value.externalId(),value.state(),value.version(),json.writeValueAsString(value));imported++;}else{sql.update("UPDATE github_work_item SET state=?,version=?,snapshot=?::jsonb WHERE item_id=?",value.state(),value.version(),json.writeValueAsString(value),item);updated++;}revision(value,actor,trace,now,old==null);}
 long version=expected+1;sql.update("INSERT INTO github_work_sync_state VALUES (?,?,?,?) ON CONFLICT(repository_id,kind) DO UPDATE SET version=excluded.version,observed_at=excluded.observed_at",repo,kind,version,java.sql.Timestamp.from(now));var receipt=new Receipt(ids.next(),repo,kind,version,now.toString(),batch.scannedCount(),batch.items().size(),imported,updated,unchanged,batch.possiblyMore());sql.update("INSERT INTO github_work_receipt VALUES (?,?,?,?,?,?,?,?,?::jsonb)",receipt.syncId(),space,repo,kind,actor,key,expected,version,json.writeValueAsString(receipt));return new Synced(state(space,repo,kind),receipt,false);});}
 static void validate(GitHubStore.Repository repo,String kind,GitHubWorkClient.Item s){if(s==null||!s.externalId().matches("[1-9][0-9]{0,18}")||s.number()<1||s.number()>9007199254740991L||!Set.of("OPEN","CLOSED").contains(s.state())||kind.equals("ISSUE")!=(s.draft()==null)||!s.url().equals(repo.url()+"/"+(kind.equals("ISSUE")?"issues":"pull")+"/"+s.number())||!GitHubRules.text(s.title(),500,true).equals(s.title())||s.authorLogin()!=null&&(!s.authorLogin().matches("[A-Za-z0-9-]+(?:\\[bot\\])?")||s.authorLogin().length()>100))throw conflict();Instant created=Instant.parse(s.createdAt()),updated=Instant.parse(s.updatedAt());if(updated.isBefore(created)||s.state().equals("OPEN")!=(s.closedAt()==null)||s.closedAt()!=null&&Instant.parse(s.closedAt()).isBefore(created))throw conflict();}
 static boolean equal(Item a,GitHubWorkClient.Item b){return a.title().equals(b.title())&&a.state().equals(b.state())&&Objects.equals(a.authorLogin(),b.authorLogin())&&Objects.equals(a.draft(),b.draft())&&a.updatedAt().equals(b.updatedAt())&&Objects.equals(a.closedAt(),b.closedAt())&&a.url().equals(b.url());}
 Item get(UUID space,UUID repo,UUID item){repositories.get(space,repo);var rows=sql.query("SELECT snapshot::text FROM github_work_item WHERE space_id=? AND repository_id=? AND item_id=?",(rs,n)->json.readValue(rs.getString(1),Item.class),space,repo,item);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Work item unavailable");return rows.getFirst();}
 Page<Item> page(UUID space,UUID repo,String kind,String state,UUID after,int limit){repositories.get(space,repo);GitHubWorkClient.kind(kind);if(!Set.of("ALL","OPEN","CLOSED").contains(state)||limit<1||limit>100)throw GitHubRules.bad();if(after!=null)GitHubRules.id(after.toString());var args=new ArrayList<Object>(List.of(space,repo,kind));if(!state.equals("ALL"))args.add(state);if(after!=null)args.add(after);args.add(limit+1);var rows=sql.query("SELECT snapshot::text FROM github_work_item WHERE space_id=? AND repository_id=? AND kind=?"+(state.equals("ALL")?"":" AND state=?")+(after==null?"":" AND item_id>?")+" ORDER BY item_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Item.class),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page<>(items,rows.size()>limit?items.getLast().itemId():null);}
 List<Revision> history(UUID space,UUID repo,UUID item,long before,int limit){get(space,repo,item);if(before<1||limit<1||limit>10)throw GitHubRules.bad();return sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM github_work_item_revision WHERE item_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Item.class)),item,before,limit);}
 SyncPage syncs(UUID space,UUID repo,String kind,Long before,int limit){state(space,repo,kind);if(before!=null&&before<1||limit<1||limit>100)throw GitHubRules.bad();var args=new ArrayList<Object>(List.of(space,repo,kind));if(before!=null)args.add(before);args.add(limit+1);var rows=sql.query("SELECT snapshot::text FROM github_work_receipt WHERE space_id=? AND repository_id=? AND kind=?"+(before==null?"":" AND sync_version<?")+" ORDER BY sync_version DESC LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Receipt.class),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new SyncPage(items,rows.size()>limit?items.getLast().syncVersion():null);}
 private void revision(Item v,UUID actor,String trace,Instant now,boolean imported){UUID revision=ids.next();sql.update("INSERT INTO github_work_item_revision VALUES (?,?,?,?,?,?::jsonb)",revision,v.itemId(),v.version(),actor,java.sql.Timestamp.from(now),json.writeValueAsString(v));var p=GitHubWorkItemObservedV1.newBuilder().setItemId(v.itemId().toString()).setRevisionId(revision.toString()).setRepositoryId(v.repositoryId().toString()).setVisibility("PRIVATE").setSourceVisibility("PUBLIC").setKind(v.kind()).setNumber(v.number()).setExternalId(v.externalId()).setRepositoryExternalId(v.repositoryExternalId()).setRepositoryFullName(v.repositoryFullName()).setTitle(v.title()).setState(v.state()).setAuthorLogin(v.authorLogin()==null?"":v.authorLogin()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt()).setClosedAt(v.closedAt()==null?"":v.closedAt()).setUrl(v.url()).setVersion(v.version()).setFirstObservedAt(v.firstObservedAt()).setObservedAt(v.observedAt());if(v.draft()!=null)p.setDraft(v.draft());UUID event=ids.next();String aggregate=v.kind().equals("ISSUE")?"github-issue":"github-pull-request",artifact=aggregate+"-events",type=imported?"GitHubWorkItemImported":"GitHubWorkItemObserved";var wire=GitHubWorkEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(now.toEpochMilli()).setProducer("integration-service").setAggregateType("GitHubWorkItem").setAggregateId(v.itemId().toString()).setSpaceId(v.spaceId().toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(p.build().toByteString()).build();sql.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,payload,schema_group,schema_artifact,schema_version,trace_id,occurred_at) VALUES (?,?,?,?,?,'integration',?,'1',?,?)",event,aggregate,v.itemId(),type,wire.toByteArray(),artifact,trace,java.sql.Timestamp.from(now));}
}
